export function evaluate({ inputs, time }) {
  const v0 = inputs.launchSpeed;
  const g = 9.8;
  const tTop = v0 / g;
  const hTop = (v0 * v0) / (2 * g);
  const v = v0 - g * time;
  const h = Math.max(0, v0 * time - 0.5 * g * time * time);

  const isTop = Math.abs(time - tTop) < 0.02;
  const isUp = !isTop && v > 0;
  const motionState = isTop ? "Still for an instant" : isUp ? "Moving up" : "Moving down";
  const gravityState = "Gravity pulls down";

  const originX = 240;
  const originY = 360;
  const scaleY = 160;
  const ballX = originX;
  const ballY = originY - h * scaleY;

  const objects = [];

  objects.push(...sdk.panel({
    id: "lane.main",
    x: 40,
    y: 20,
    w: 560,
    h: 380,
    title: "Toss Motion & Gravity",
    state: motionState
  }));

  objects.push(sdk.axis("axis.height", {
    x: 120,
    y: originY,
    length: 300,
    orientation: "y",
    min: 0,
    max: 2.0,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.groundMark("heightGuide", ballX, originY, 140, "Launch Height (0.0 m)"));

  objects.push(sdk.line("guide.maxHeight", ballX - 60, originY - hTop * scaleY, ballX + 60, originY - hTop * scaleY, {
    role: "prediction",
    opacity: 0.6
  }));

  objects.push(sdk.circle("ball.toss", ballX, ballY, 32));

  if (!isTop) {
    objects.push(...sdk.vector("vec.v", {
      x: ballX - 30,
      y: ballY
    }, {
      value: v,
      direction: "up",
      scale: 18,
      label: "v",
      role: "learner"
    }));
  }

  objects.push(...sdk.vector("vec.a", {
    x: ballX + 30,
    y: ballY
  }, {
    value: -g,
    direction: "up",
    scale: 6,
    label: "a",
    role: "warning"
  }));

  objects.push(...sdk.callout(ballX + 70, ballY - 20, [motionState, gravityState], {
    id: "callout.toss"
  }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionState },
        { id: "gravityState", value: gravityState }
      ]
    },
    quantities: {
      launchSpeed: v0,
      gravity: g,
      apexTime: tTop,
      apexHeight: hTop,
      velocity: v,
      height: h
    }
  };
}
